#include <mpi.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(int argc,char **argv){MPI_Init(&argc,&argv);int rank,size;MPI_Comm_rank(MPI_COMM_WORLD,&rank);MPI_Comm_size(MPI_COMM_WORLD,&size);if(size!=2 || argc<3)MPI_Abort(MPI_COMM_WORLD,2);size_t n=strtoull(argv[1],NULL,10);int loops=atoi(argv[2]);const char *method=argc>3?argv[3]:"bad";if(n<1||n>64*1024*1024 || loops<1)MPI_Abort(MPI_COMM_WORLD,3);char *send=malloc(n),*recv=malloc(n);memset(send,rank,n);MPI_Barrier(MPI_COMM_WORLD);double start=MPI_Wtime();for(int k=0;k<loops;k++){if(!strcmp(method,"bad")){MPI_Send(send,n,MPI_BYTE,1-rank,10,MPI_COMM_WORLD);MPI_Recv(recv,n,MPI_BYTE,1-rank,10,MPI_COMM_WORLD,MPI_STATUS_IGNORE);}else if(!strcmp(method,"ordered")){if(rank==0){MPI_Send(send,n,MPI_BYTE,1,10,MPI_COMM_WORLD);MPI_Recv(recv,n,MPI_BYTE,1,10,MPI_COMM_WORLD,MPI_STATUS_IGNORE);}else{MPI_Recv(recv,n,MPI_BYTE,0,10,MPI_COMM_WORLD,MPI_STATUS_IGNORE);MPI_Send(send,n,MPI_BYTE,0,10,MPI_COMM_WORLD);}}else{MPI_Request req[2];MPI_Irecv(recv,n,MPI_BYTE,1-rank,10,MPI_COMM_WORLD,&req[0]);MPI_Isend(send,n,MPI_BYTE,1-rank,10,MPI_COMM_WORLD,&req[1]);MPI_Waitall(2,req,MPI_STATUSES_IGNORE);}if(recv[0]!=(char)(1-rank))MPI_Abort(MPI_COMM_WORLD,4);}double t=(MPI_Wtime()-start)/loops,m;MPI_Reduce(&t,&m,1,MPI_DOUBLE,MPI_MAX,0,MPI_COMM_WORLD);if(rank==0)printf("тупик метод=%s байти=%zu повтори=%d час=%.12f статус=успішно\n",method,n,loops,m);free(send);free(recv);MPI_Finalize();return 0;}
